using System;using System.IO;using System.Linq;using System.Collections.Generic;
partial class ShortcutProbe {
 static int RunPaired(EnvDTE.DTE d,int pid,string role,string root,string planFile){
 if(!d.Solution.FullName.StartsWith(Path.GetFullPath(".local/parity-runs")+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Refusing non-owned solution");
 var plan=(Dictionary<string,object>)json.DeserializeObject(File.ReadAllText(planFile));var rows=new List<object>();Console.WriteLine("Solution="+d.Solution.FullName+" count="+d.Solution.Projects.Count);foreach(EnvDTE.Project project in d.Solution.Projects)Console.WriteLine("Project="+project.Name+" file="+project.FullName);
 if(!Path.GetFullPath(root).Contains("CodeAssist\\docs\\validation\\paired-098"))throw new Exception("Unowned fixture output");
 foreach(Dictionary<string,object> c in (object[])plan["cases"]){string id=(string)c["id"],file=Path.Combine(root,id+".cpp"),error=null;object before=null,after=null,undo=null;bool executed=false;try{
 File.WriteAllText(file,(string)c["text"]);var projectItems=d.Solution.Projects.Cast<EnvDTE.Project>().Where(p=>p.FullName.EndsWith("Parity.vcxproj",StringComparison.OrdinalIgnoreCase)).ToArray();if(projectItems.Length!=1)throw new Exception("Expected one owned fixture project");projectItems[0].ProjectItems.AddFromFile(file);d.ItemOperations.OpenFile(file).Activate();Pump(1500);AssertNoBlockingDialog(d);var s=(EnvDTE.TextSelection)d.ActiveDocument.Selection;s.StartOfDocument(false);int start=Convert.ToInt32(c["start"]),length=Convert.ToInt32(c["length"]);int moves=((string)c["text"]).Substring(0,start).Replace("\r\n","\n").Length;if(moves>0)s.CharRight(false,moves);moves=((string)c["text"]).Substring(start,length).Replace("\r\n","\n").Length;if(moves>0)s.CharRight(true,moves);FocusEditor(d,pid,file);before=BufferSnapshot(d,file);CapturePhase(d,root,id,"before");
 System.Diagnostics.Process worker=null;if(id=="sort-lines"||(role=="CA"&&(id=="toggle-braces"||id=="create-implementation"))){worker=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"PairedDialogWorker.exe"),pid+" "+id+" "+Path.Combine(root,id+"-dialog.log")){UseShellExecute=false,CreateNoWindow=true});}
 if(c.ContainsKey("keys")){foreach(string chord in (object[])c["keys"]){Keys(pid,chord.Split('+').Select(Key).ToArray());Pump(350);}}
 else if(role=="VA")d.ExecuteCommand((string)c["vaCommand"],"");else{object a=null,b=null;d.Commands.Raise("{f9d77864-fac8-457e-bd4f-552715151b6c}",Convert.ToInt32(c["caCommand"]),ref a,ref b);}executed=true;if(worker!=null){var deadline=DateTime.UtcNow.AddSeconds(9);while(!worker.HasExited&&DateTime.UtcNow<deadline)Pump(100);}Pump(800);AssertNoBlockingDialog(d);after=BufferSnapshot(d,file);CapturePhase(d,root,id,"after");
 if(Convert.ToBoolean(c["undo"])) {d.ExecuteCommand("Edit.Undo","");Pump(250);undo=BufferSnapshot(d,file);CapturePhase(d,root,id,"undo");}
 }catch(Exception ex){error=ex.ToString();}finally{try{if(d.ActiveDocument!=null&&d.ActiveDocument.FullName==file)d.ActiveDocument.Close(EnvDTE.vsSaveChanges.vsSaveChangesNo);}catch{}}
 rows.Add(new{id,feature=c["feature"],before,after,undo,error,executed});File.WriteAllText(Path.Combine(root,role+".json"),json.Serialize(new{role,pid,planHash=FileHash(planFile),cases=rows,finishedAt=DateTimeOffset.Now}));Console.WriteLine(role+" "+id+" executed="+executed+" error="+(error??"none"));
 }return 0;}
 static string FileHash(string file){using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(file))).Replace("-","").ToLowerInvariant();}
}
